// 客户端
DatagramSocket socket = new DatagramSocket();                 // 系统自动给一个本地端口
byte[] data = "hello".getBytes();
InetAddress address = InetAddress.getByName("server.example");  // 目的 IP
DatagramPacket packet = new DatagramPacket(data, data.length, address, 9876); // 装上目的 IP 和端口
socket.send(packet);

// 服务器
DatagramSocket server = new DatagramSocket(9876);              // 绑定一个固定端口
byte[] buf = new byte[1024];
while (true) {
    DatagramPacket p = new DatagramPacket(buf, buf.length);
    server.receive(p);                                          // 阻塞，等一个数据报
    // p.getAddress() 和 p.getPort() 就是发送方的 IP 和端口，可用来回复
}
